sections.code:
Bind blog:posts with alias news, limit 3 and an optional category ID.

{{#news.items}}
  <article>
    <h2><a href="{{href}}">{{title}}</a></h2>
    <p>{{excerpt}}</p>
    {{#tags}}<span>{{.}}</span>{{/tags}}
  </article>
{{/news.items}}
{{^news.items}}<p>No articles yet.</p>{{/news.items}}
